    node_id: str | None = None
    """审批节点 ID。必须同时满足："""
    node_name: str | None = None
    """节点名称，这里返回的是 i18n_resources.texts 参数的 key，对应的取值需要参见返回的 i18n_resources.texts.value。"""
    generate_type: str | None = None
