class ExternalInstance(FeishuModel):
    """同步的实例数据"""

    approval_code: str | None = None
    """审批定义 Code"""
    status: str | None = None
    """审批实例状态"""
    extra: str | None = None
    """审批实例扩展 JSON。单据编号通过传 business_key 字段来实现。"""
    instance_id: str | None = None
    """审批实例唯一标识，与请求时传入的 instance_id 一致。"""
    links: ExternalInstanceLink | None = None
    """审批实例链接信息。设置的链接用于在审批中心 已发起 列表内点击跳转，跳回三方审批系统查看审批详情。"""
    title: str | None = None
    """审批展示名称。"""
    form: list[ExternalInstanceForm] | None = None
    """用户提交审批时填写的表单数据，用于所有审批列表中展示。可传多个值，最多展示前 3 个。"""
    user_id: str | None = None
    """审批发起人 user_id。发起人可在审批中心的 已发起 列表中看到所有已发起的审批。在 待办、已办、抄送我 列表中，该字段用来展示审批的发起人。"""
    user_name: str | None = None
    """审批发起人的用户名。如果发起人不是真实的用户（例如是某个部门），没有 user_id，则可以使用该参数传入一个名称。"""
    open_id: str | None = None
    """审批发起人 open_id。发起人可在审批中心的 已发起 列表中看到所有已发起的审批。在 待办、已办、抄送我 列表中，该字段用来展示审批的发起人。"""
    department_id: str | None = None
    """发起人的部门 ID，用于在审批中心列表中展示发起人的所属部门，不传值则不展示。"""
    department_name: str | None = None
    """审批发起人的部门名称。如果发起人不是真实的用户或没有部门，则可以使用该参数传入部门名称。"""
    start_time: str | None = None
    """审批发起时间，Unix 毫秒时间戳。"""
    end_time: str | None = None
    """审批实例结束时间。未结束的审批为 0，Unix 毫秒时间戳。"""
    update_time: str | None = None
    """审批实例最近更新时间，Unix 毫秒时间戳，用于推送数据版本控制。如果 update_mode 值为 UPDATE，则仅当传过来的 update_time 有变化时（变大），才会更新审批中心中的审批实例信息。 说明：使用该参数主要用来避免并发时，旧数据更新了新数据。"""
    display_method: str | None = None
    """列表页打开审批实例的方式"""
    update_mode: str | None = None
    """更新方式。 - 当 update_mode 取值为 REPLACE 时，每次都以当前推送的数据为最终数据，会删掉审批中心中，不在本次推送数据中的多余的任务、抄送数据。 - 当 update_mode 取值为 UPDATE 时，不会删除审批中心的数据，而只进行新增、更新实例与任务数据。"""
    task_list: list[ExternalInstanceTaskNode] | None = None
    """任务列表"""
    cc_list: list[CcNode] | None = None
    """抄送列表"""
    i18n_resources: list[I18nResource] | None = None
    """国际化文案"""
    trusteeship_url_token: str | None = None
    """单据托管认证 token，托管回调会附带此 token，帮助业务认证。"""
    trusteeship_user_id_type: str | None = None
    """用户的类型，会影响请求参数用户标识域的选择，包括加签操作回传的目标用户， 目前仅支持 user_id。"""
    trusteeship_urls: TrusteeshipUrls | None = None
    """单据托管回调接入方的接口 URL 地址"""
    trusteeship_cache_config: TrusteeshipInstanceCacheConfig | None = None
    """托管预缓存策略"""
    resource_region: str | None = None
    """资源所在地区， 内部统计用字段， 不需要填"""


